import{_ as t}from"./chunks/icon.B7gRmRZx.js";import{_ as s,a as r,b as o,c as a,d as i,e as n,f as l,g as u,h as c,i as d,j as p,k as m,l as g}from"./chunks/0.1.12-193-neustart-de.DMY_PLph.js";import{_ as h,o as b,c as v,a3 as f}from"./chunks/framework.BlfGB29P.js";const E=JSON.parse('{"title":"Logic Studio","description":"HA Logic Studio Pro 0.1.67 · Import ioBroker étendu dans Blocks JS","frontmatter":{"title":"Logic Studio","description":"HA Logic Studio Pro 0.1.67 · Import ioBroker étendu dans Blocks JS"},"headers":[],"relativePath":"fr/projects/logic-studio/index.md","filePath":"fr/projects/logic-studio/index.md","lastUpdated":1794566710000}'),L={name:"fr/projects/logic-studio/index.md"};function A(x,e,k,q,S,H){return b(),v("div",null,[...e[0]||(e[0]=[f('<h1 id="logic-studio" tabindex="-1"><img class="package-icon" src="'+t+'" width="40" height="40" alt=""> Logic Studio <a class="header-anchor" href="#logic-studio" aria-label="Permalink to &quot;&lt;img class=&quot;package-icon&quot; src=&quot;/images/logic-studio/icon.svg&quot; width=&quot;40&quot; height=&quot;40&quot; alt=&quot;&quot;&gt; Logic Studio&quot;">​</a></h1><p><strong>0.1.12 – mise à jour publique de test, 8 novembre 2026.</strong> Interface et documentation sont désormais disponibles en <strong>DE/EN/FR</strong>. Logic Studio est une application HA autonome pour les plans à blocs fonctionnels, indépendante de Grafik Visual Studio et Blocks for HA. Le canevas React Flow conserve ses blocs personnalisés, connexions typées, zoom et MiniMap ; bibliothèques et licences sont incluses localement.</p><div class="warning custom-block"><p class="custom-block-title">Version de test</p><p>Installer d’abord sur un système de test et créer une sauvegarde complète. Les propriétés natives détaillées sont actuellement modifiables en JSON. L’application ne réécrit pas les automatisations/scripts dans HA et ne commande aucun appareil. Vérifier et installer soi-même les sorties générées.</p></div><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/logic-studio-v0.1.12" target="_blank" rel="noreferrer">Version de test GitHub et ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/logic_studio" target="_blank" rel="noreferrer">Sources dans le dépôt commun</a></p><h2 id="ha-logic-studio-pro-0-1-67" tabindex="-1">HA Logic Studio Pro 0.1.67 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-67" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.67&quot;">​</a></h2><p>Version de test publique actuelle. Créer une sauvegarde complète et essayer la mise à jour sur un système de test.</p><p>Les blocs importés de vérification de l’existence d’un état et d’identifiant d’objet conservent leur identifiant ioBroker. Associez explicitement chaque identifiant à une entité Home Assistant dans le bloc. Blocks JS retrouve les données Blockly intégrées dans un fichier JavaScript même si d’autres commentaires les suivent.</p><p>La section <strong>Adaptations du code requises</strong> de l’aperçu explique comment remplacer les blocs non pris en charge, comme <code>exec</code>. Après une sauvegarde complète sur <code>.193</code>, des fichiers de test XML et JavaScript ont été importés et les nouveaux champs d’association ont été vérifiés dans l’éditeur.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.67" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.67 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-66" tabindex="-1">HA Logic Studio Pro 0.1.66 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-66" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.66&quot;">​</a></h2><p>Activez la sauvegarde des compteurs et des mémoires dans le diagramme fonctionnel, puis enregistrez le projet. Les blocs CTU, CTD, CTUD, RS et SR peuvent retrouver leurs valeurs après le redémarrage de l’application.</p><p>Le rapport d’import de Blocks JS répertorie séparément les identifiants ioBroker calculés. Dans le champ d’association JSON du bloc importé, associez chaque identifiant ioBroker possible à une entité Home Assistant.</p><p>Sur <code>.193</code>, le compteur CTU et la mémoire RS ont conservé les valeurs <code>1</code> et <code>true</code> après le redémarrage de l’application.</p><p>Lors du test en conditions réelles sur <code>.193</code>, le script Blocks JS importé a calculé l’identifiant ioBroker <code>zigbee.0.sensor</code>. L’association JSON lui a permis de lire l’assistant de test Home Assistant <code>input_boolean.logic_studio_runtime_test</code>. Deux lancements avec le bouton de lecture ont inscrit <code>false</code> dans le journal lorsque l’assistant était désactivé et <code>true</code> lorsqu’il était activé.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.66" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.66 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-65" tabindex="-1">HA Logic Studio Pro 0.1.65 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-65" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.65&quot;">​</a></h2><h3 id="demarrage-automatique-simulation-et-import-iobroker" tabindex="-1">Démarrage automatique, simulation et import ioBroker <a class="header-anchor" href="#demarrage-automatique-simulation-et-import-iobroker" aria-label="Permalink to &quot;Démarrage automatique, simulation et import ioBroker&quot;">​</a></h3><p>Les projets JavaScript, TypeScript et les diagrammes fonctionnels peuvent être exécutés au démarrage de l’application. Activer <strong>Exécuter au démarrage de l’application</strong> et enregistrer le projet. La simulation propose des points d’arrêt et le pas à pas. L’organisation automatique conserve la position des blocs épinglés. L’aperçu d’import ioBroker de Blocks JS liste les blocs non pris en charge et les identifiants fixes à associer.</p><p>Sur <code>.193</code>, le projet de test JavaScript enregistré a démarré automatiquement après le redémarrage de l’application. Un point d’arrêt, un pas de simulation et l’aperçu d’import ioBroker avec un identifiant fixe ont également été vérifiés.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.65" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.65 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-62" tabindex="-1">HA Logic Studio Pro 0.1.62 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-62" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.62&quot;">​</a></h2><p>HA Logic Studio Pro est une application Home Assistant autonome dans le dépôt commun UGSo. Elle s’appuie sur Logic Studio et sur l’expérience acquise avec ioBroker.</p><p><strong>Fonctionnalités disponibles</strong></p><ul><li><strong>Diagramme fonctionnel :</strong> Relier les blocs, afficher les signaux aux entrées et simuler le diagramme. Sur le serveur HA, l’exécution peut réagir aux changements ou suivre un cycle fixe.</li><li><strong>Règles et Blocks A :</strong> Créer des automatisations dans un éditeur visuel et les exporter au format YAML de HA.</li><li><strong>Blocks JS, JavaScript et TypeScript :</strong> Modifier la logique, la tester avec des valeurs simulées et l’exécuter sur le serveur HA.</li><li><strong>YAML HA :</strong> Modifier, valider et exporter les automatisations et les scripts.</li><li><strong>Gestion des projets :</strong> Enregistrer les projets et les dossiers sur le serveur pour chaque utilisateur HA.</li><li><strong>Choix de la langue :</strong> Les éditeurs sont disponibles en allemand, en anglais et en français.</li></ul><p>La version <strong>0.1.62</strong> a ajouté les fonctions de règles décrites ci-dessous.</p><h3 id="regles-enrichies-et-test-en-conditions-reelles-sur-193" tabindex="-1">Règles enrichies et test en conditions réelles sur .193 <a class="header-anchor" href="#regles-enrichies-et-test-en-conditions-reelles-sur-193" aria-label="Permalink to &quot;Règles enrichies et test en conditions réelles sur .193&quot;">​</a></h3><p>Les déclencheurs d’état prennent en charge les valeurs de départ et d’arrivée, un attribut et une durée minimale. Les conditions vérifient les états, les attributs et les seuils numériques. Les branches ALORS et SINON proposent un sélecteur d’actions HA avec des paramètres JSON et des étapes de temporisation distinctes.</p><p>L’éditeur et le sélecteur d’actions ont été testés localement dans le navigateur. Après une sauvegarde complète, le YAML généré a été exécuté directement dans Home Assistant sur <code>.193</code>. Une impulsion brève n’a rien déclenché. Un état maintenu trois secondes a exécuté ALORS. Un changement du nom d’affichage a exécuté SINON. Les deux traces ont confirmé le délai de deux secondes et la valeur de texte attendue. L’automatisation et les deux auxiliaires de test ont été supprimés.</p><p>Les nouveaux blocs s’exportent en YAML HA. Rules → JS indique si un bloc empêche la conversion.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.62" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.62 · GitHub / ZIP</a></p><h3 id="export-yaml-et-test-en-conditions-reelles-sur-193" tabindex="-1">Export YAML et test en conditions réelles sur .193 <a class="header-anchor" href="#export-yaml-et-test-en-conditions-reelles-sur-193" aria-label="Permalink to &quot;Export YAML et test en conditions réelles sur .193&quot;">​</a></h3><p>L’export des règles conserve les états tels que <code>on</code> et <code>off</code> sous forme de texte, sans les convertir en booléens YAML. L’automatisation corrigée a été exécutée directement dans Home Assistant sur <code>.193</code> avec des entrées de test.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Déclencheur</th><th>Condition</th><th>Résultat de la trace HA</th></tr></thead><tbody><tr><td>Changement d’état</td><td>OU satisfaite</td><td>Deux actions ALORS</td></tr><tr><td>Changement d’état</td><td>ET non satisfaite</td><td>Deux actions SINON</td></tr><tr><td>Événement HA</td><td>Condition NON vraie</td><td>Deux actions ALORS</td></tr><tr><td>Heure 20:26</td><td>Condition NON fausse</td><td>Deux actions SINON</td></tr></tbody></table></div><p>Une sauvegarde complète a été créée avant le test. L’automatisation et les trois entrées de test ont ensuite été supprimées.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.61" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.61 · GitHub / ZIP</a></p><h3 id="regles-palette-compacte-et-declencheurs-multiples" tabindex="-1">Règles : palette compacte et déclencheurs multiples <a class="header-anchor" href="#regles-palette-compacte-et-declencheurs-multiples" aria-label="Permalink to &quot;Règles : palette compacte et déclencheurs multiples&quot;">​</a></h3><p>L’éditeur affiche une liste compacte avec des icônes à gauche. Une règle peut combiner des changements d’état, une heure quotidienne et des événements Home Assistant. Les conditions acceptent ET, OU et NON. Les branches ALORS et SINON exécutent plusieurs actions dans l’ordre affiché.</p><p>Sur le système <code>.193</code>, une règle existante a été testée avec trois déclencheurs, deux conditions et deux actions par branche. L’aperçu YAML présentait la structure attendue. Lors du test dans Studio, les trois déclencheurs simulés ont lancé les deux actions ALORS lorsque la condition OU était satisfaite. Lorsque la condition ET ne l’était pas, les deux actions SINON se sont exécutées dans l’ordre configuré. Aucun appareil réel n’a été commandé.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.60" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.60 · GitHub / ZIP</a></p><p><img src="'+s+'" alt="Éditeur de règles sur .193 avec la palette compacte et les deux branches"></p><h3 id="creer-une-regle-avec-l-assistant" tabindex="-1">Créer une règle avec l’assistant <a class="header-anchor" href="#creer-une-regle-avec-l-assistant" aria-label="Permalink to &quot;Créer une règle avec l’assistant&quot;">​</a></h3><p>Choisissez <strong>Règles → Assistant</strong>. Le dialogue suit quatre étapes : <strong>Déclencheur → Conditions → Actions → Récapitulatif</strong>. Une règle peut réagir à un changement d’état, à une heure quotidienne dans le fuseau horaire de HA ou à un événement Home Assistant. Les conditions et la branche SINON sont facultatives. Le récapitulatif affiche l’aperçu YAML. <strong>Appliquer</strong> transfère le brouillon dans l’éditeur ; <strong>Enregistrer</strong> le conserve. Les règles existantes restent modifiables et peuvent être ouvertes en JavaScript ou en YAML HA.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.59" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.59 · GitHub / ZIP</a></p><p>Le 12 novembre 2026, les trois déclencheurs ont été testés directement dans Home Assistant sur le système de test <code>.193</code>. Le passage de l’état désactivé à l’état activé, le déclenchement quotidien à 19 h 38 (heure locale de HA) et l’événement <code>rules_live_0159_event</code> ont chacun activé la sortie de test. Une sauvegarde complète a été créée avant le test. Les trois automatisations et les deux assistants de test ont ensuite été supprimés.</p><p><img src="'+r+`" alt="Home Assistant affiche la dernière exécution des trois automatisations de test et la sortie de test activée"></p><h3 id="nouveautes-depuis-la-version-0-1-12" tabindex="-1">Nouveautés depuis la version 0.1.12 <a class="header-anchor" href="#nouveautes-depuis-la-version-0-1-12" aria-label="Permalink to &quot;Nouveautés depuis la version 0.1.12&quot;">​</a></h3><ul><li><strong>Arborescence et éditeurs.</strong> Les projets et dossiers sont enregistrés sur le serveur pour chaque utilisateur HA. Les projets locaux peuvent être migrés au premier démarrage depuis le navigateur d’origine. JavaScript et TypeScript disposent de la coloration syntaxique, de numéros de ligne et de barres d’outils dédiées. Les icônes et couleurs correspondent entre le sélecteur, l’arborescence et les filtres. Blocks A et Blocks JS ont des filtres distincts. La largeur automatique du volet reste réglable par la poignée.</li><li><strong>Blocks A et Blocks JS.</strong> Blocks A utilise le catalogue intégré de Blocks for HA. Blocks JS dispose de sa propre palette JavaScript. Blocks A exporte des automatisations HA en YAML. Blocks JS génère le JavaScript pour la simulation et le moteur. Les blocs ioBroker inconnus sont conservés sous forme de blocs de remplacement et bloquent la génération du code jusqu’à leur remplacement. Associer les identifiants d’objets ioBroker aux entités HA correspondantes.</li><li><strong>Diagramme fonctionnel.</strong> La barre supérieure comporte les icônes de simulation, d’avancement d’une seconde et de réinitialisation. Le format de sortie et l’aperçu sont à droite. Les connexions peuvent être déplacées vers une autre entrée et les valeurs des signaux s’affichent à l’entrée cible.</li><li><strong>Moteur serveur.</strong> Le bouton de lecture lance JavaScript, TypeScript transpilé ou Blocks JS sur le serveur HA. L’arrêt et le redémarrage sont disponibles dans l’éditeur. L’état et le journal restent accessibles depuis un autre navigateur. Le <strong>test</strong> séparé utilise des états et événements simulés. Les scripts et automatisations YAML sont exécutés par Home Assistant après import.</li></ul><h3 id="configurer-le-moteur-en-direct" tabindex="-1">Configurer le moteur en direct <a class="header-anchor" href="#configurer-le-moteur-en-direct" aria-label="Permalink to &quot;Configurer le moteur en direct&quot;">​</a></h3><p>Dans <strong>Paramètres → Applications → HA Logic Studio Pro → Configuration</strong>, ajouter les entrées nécessaires, enregistrer puis redémarrer l’application. Les listes sont vides par défaut. Exemple avec une entrée booléenne dédiée au test :</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_read_entities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_write_entities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">input_boolean.logic_studio_runtime_test</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">logic_studio_runtime_test</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>L’autorisation d’écriture inclut la lecture. <code>ha.readState</code> et <code>ha.readAttribute</code> renvoient les dernières valeurs confirmées par HA. <code>ha.onState</code>, <code>ha.onAttribute</code> et <code>ha.onEvent</code> réagissent aux changements et événements autorisés. <code>ha.callAction</code> permet la commutation, la modification des entrées numériques, textuelles ou de sélection et l’appui sur des boutons pour une cible autorisée. <code>ha.schedule</code> accepte des motifs horaires et des heures fixes, avec des jours de la semaine facultatifs, dans le fuseau horaire de HA.</p><p>Après le redémarrage de l’application, les scripts doivent être relancés. En cas de perte de connexion ou de refus d’une action, le moteur arrête le script et journalise l’erreur. Les déclencheurs astronomiques et la reconnexion automatique restent à ajouter.</p><p><strong>Vérifié sur .193 avec HA 2026.11.1.</strong> Le moteur a lu l’état et un attribut de l’entrée de test, l’a activée par un horaire et l’a désactivée à la réception d’un événement HA réel. Les deux changements d’état ont été signalés. Un horaire Blocks JS importé s’est exécuté toutes les deux secondes. Les tests précédents ont vérifié le démarrage, l’arrêt, le redémarrage et la poursuite de l’exécution après avoir quitté Studio, avec JavaScript et TypeScript.</p><h3 id="commander-des-scripts-et-des-automatisations" tabindex="-1">Commander des scripts et des automatisations <a class="header-anchor" href="#commander-des-scripts-et-des-automatisations" aria-label="Permalink to &quot;Commander des scripts et des automatisations&quot;">​</a></h3><p>Dans <strong>Blocks JS → Système</strong>, choisissez une entité Home Assistant avec <strong>Choisir un script ou une automatisation</strong>, puis reliez le bloc à <strong>Commander</strong>. Vous pouvez démarrer ou arrêter les scripts, ainsi qu’activer, désactiver ou déclencher une fois les automatisations. L’option <strong>Vérifier les conditions</strong> est activée par défaut lors du déclenchement. Décochez-la pour ignorer les conditions. Pour l’exécution réelle, autorisez l’entité cible dans <code>runtime_write_entities</code>.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.58" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.58 · GitHub et ZIP</a></p><h3 id="fonctions-et-import-iobroker" tabindex="-1">Fonctions et import ioBroker <a class="header-anchor" href="#fonctions-et-import-iobroker" aria-label="Permalink to &quot;Fonctions et import ioBroker&quot;">​</a></h3><p><strong>Blocks JS → Fonctions</strong> propose deux blocs de fonction JavaScript, avec ou sans valeur de retour. Utilisez l’engrenage pour définir les paramètres et <strong>…</strong> pour modifier le code. Après l’ajout d’une définition, son bloc d’appel apparaît dans la palette.</p><p>L’import ioBroker conserve les définitions, les appels, les paramètres et le code JavaScript. Adaptez les appels propres à ioBroker au moteur HA et associez explicitement les identifiants d’objet importés aux entités HA.</p><h3 id="interroger-l-historique" tabindex="-1">Interroger l’historique <a class="header-anchor" href="#interroger-l-historique" aria-label="Permalink to &quot;Interroger l’historique&quot;">​</a></h3><p>Utilisez <strong>Blocks JS → Sendto → Interroger l’historique</strong> pour lire les états enregistrés par HA Recorder. Sans période indiquée, la requête utilise la journée en cours dans le fuseau horaire de HA. Le bloc de résultat renvoie des valeurs horodatées. L’import ioBroker conserve la période, l’agrégation, le pas et le nombre de résultats.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.57" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.57 · GitHub et ZIP</a></p><h3 id="_0-1-29-·-enregistrement-manuel-et-editeurs-de-blocs" tabindex="-1">0.1.29 · Enregistrement manuel et éditeurs de blocs <a class="header-anchor" href="#_0-1-29-·-enregistrement-manuel-et-editeurs-de-blocs" aria-label="Permalink to &quot;0.1.29 · Enregistrement manuel et éditeurs de blocs&quot;">​</a></h3><p>Dans tous les éditeurs, <strong>Enregistrer</strong> applique les modifications. <strong>Annuler</strong> restaure la dernière version enregistrée ou abandonne un nouveau projet. Les modifications non enregistrées désactivent <strong>Démarrer</strong> et <strong>Redémarrer</strong>. Il reste possible d’arrêter un script en cours. Blocks A ouvre le sélecteur d’entités directement depuis le champ du bloc. Blocks JS propose une palette inspirée d’ioBroker avec des entités, des actions et des déclencheurs HA, sans Jinja.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.29" target="_blank" rel="noreferrer">Version de test et ZIP</a></p><h3 id="_0-1-28-·-traductions-des-editeurs" tabindex="-1">0.1.28 · Traductions des éditeurs <a class="header-anchor" href="#_0-1-28-·-traductions-des-editeurs" aria-label="Permalink to &quot;0.1.28 · Traductions des éditeurs&quot;">​</a></h3><p>La version <strong>0.1.28</strong> complète les traductions des éditeurs de règles, Blocks A, Blocks JS, JavaScript, TypeScript et YAML HA. Le choix de langue s’applique aussi au diagramme fonctionnel. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.28" target="_blank" rel="noreferrer">Version de test et ZIP</a></p><p>Les tests sur .193 ont vérifié dans les trois langues les barres d’outils du diagramme fonctionnel, des règles, de Blocks A, de Blocks JS, de JavaScript, de TypeScript, des automatisations HA et des scripts HA. La boîte de dialogue des exemples de code a aussi été vérifiée en français.</p><p>Pour installer la version Pro, sélectionner <strong>HA Logic Studio Pro</strong> dans le dépôt commun UGSo de la boutique d’applications. Pour une installation GitHub existante, rechercher les mises à jour puis sélectionner <strong>HA Logic Studio Pro → Mettre à jour</strong>. Utiliser <strong>DE</strong>, <strong>EN</strong> ou <strong>FR</strong> en haut du volet des projets pour changer la langue des éditeurs.</p><h3 id="_0-1-26-·-fbd-runtime" tabindex="-1">0.1.26 · FBD Runtime <a class="header-anchor" href="#_0-1-26-·-fbd-runtime" aria-label="Permalink to &quot;0.1.26 · FBD Runtime&quot;">​</a></h3><p>Le bouton <strong>Lecture</strong> lance le diagramme fonctionnel sur le serveur HA. Le mode <strong>Automatique</strong> réagit aux changements des états et attributs autorisés ; le <strong>Cycle fixe</strong> évalue le plan toutes les 100 à 60 000 ms. La simulation et l’export YAML restent séparés. <strong>Enregistrer</strong> valide le brouillon ; <strong>Annuler</strong> rétablit le dernier état enregistré. La barre d’outils est disponible en DE/EN/FR.</p><p>Sur .193, le démarrage automatique a activé l’entité de test et le cycle de 200 ms l’a désactivée. L’arrêt et l’annulation d’une modification non enregistrée ont aussi été vérifiés. Les deux modes ont également été testés localement avec des changements d’entrée.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.26" target="_blank" rel="noreferrer">Mise à jour de test GitHub et ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_logic_studio_pro" target="_blank" rel="noreferrer">Application dans le dépôt commun</a></p><h2 id="installation-de-test-depuis-github" tabindex="-1">Installation de test depuis GitHub <a class="header-anchor" href="#installation-de-test-depuis-github" aria-label="Permalink to &quot;Installation de test depuis GitHub&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/supervisor_add_addon_repository/?repository_url=https%3A%2F%2Fgithub.com%2Frockbaer2007%2Fugso-ha-mqtt-addons" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/supervisor_add_addon_repository.svg" alt="Ajouter le dépôt à Home Assistant"></a></p><ol><li>Dans <strong>Paramètres → Applications → Boutique d’applications → Dépôts</strong>, ajouter l’adresse ci-dessous. Si « UGSo HA Apps » est déjà configuré, rechercher les mises à jour.</li><li>Sélectionner et installer <strong>UGSo Logic Studio</strong>. Activer le mode avancé du profil HA si les applications expérimentales sont masquées.</li><li>Démarrer puis ouvrir l’interface. Compatible <strong>HA OS/Supervised</strong>, <strong>amd64 et aarch64</strong>. La première construction du conteneur peut prendre plusieurs minutes. Ce n’est pas un paquet frontend HACS/Marketplace.</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Conserver une installation locale existante :</strong> les applications GitHub et locale ont des identifiants de dépôt et des données séparés. Exporter l’ancien plan en JSON avec <strong>Projekt</strong>, puis utiliser <strong>Öffnen</strong> dans l’application GitHub. Aucune migration ou désinstallation automatique. Chaque application conserve projet et réglages de palette sous <code>/data</code>.</p><p><strong>Mettre à jour une application GitHub existante :</strong> sauvegarder d’abord, rechercher les mises à jour dans le gestionnaire d’applications puis choisir <strong>UGSo Logic Studio → Mettre à jour</strong>. Conserver l’installation : <code>/data</code>, les identifiants d’entités et les plans existants sont préservés. Ne pas désinstaller ni changer d’identifiant d’application. Sur .193, le plan original, les favoris, les blocs récents et les catégories repliées ont été conservés après la mise à jour.</p><h2 id="langue-barre-d-outils-et-documentation" tabindex="-1">Langue, barre d’outils et documentation <a class="header-anchor" href="#langue-barre-d-outils-et-documentation" aria-label="Permalink to &quot;Langue, barre d’outils et documentation&quot;">​</a></h2><p>Choisir <strong>Langue → Deutsch / English / Français</strong> dans l’en-tête. Menus, descriptions des blocs, sélecteur d’entités et dialogues d’import/export changent sans rechargement. Le choix est enregistré avec les préférences du navigateur/de l’application. <strong>Noms personnels, identifiants d’entités, valeurs, noms des bornes et code YAML/JavaScript généré ne sont pas traduits.</strong></p><p><strong>Documentation</strong>, à droite, présente les raccourcis implémentés et, pour le bloc sélectionné, sa description et ses entrées/sorties. <strong>Ctrl+Z / Ctrl+Y</strong> : annuler/rétablir ; <strong>Suppr</strong> : supprimer la sélection ; <strong>Échap</strong> : annuler une connexion/fermer un menu. Tab et Entrée/Espace permettent de choisir et connecter les bornes. Les commandes du débogueur de l’éditeur de référence ioBroker ne sont pas présentées comme disponibles.</p><p>La barre regroupe <strong>Annuler/rétablir → Projet → Simulation → Sortie</strong>. Les trois boutons de simulation ont les mêmes dimensions et des bordures distinctes. Le menu Projet propose aussi <strong>Nouveau projet</strong> et <strong>Charger l’exemple</strong>. Le sélecteur d’entités s’ouvre via l’icône <strong>à côté de l’identifiant d’entité HA</strong> dans les propriétés STATE_IN/STATE_OUT ; l’ancien bouton supérieur est retiré.</p><p><img src="`+o+'" alt="Documentation allemande sur .193 avec le plan original conservé"></p><p><img src="'+a+'" alt="Documentation anglaise du même plan sur .193"></p><p><img src="'+i+'" alt="Documentation française du même plan sur .193"></p><h2 id="deux-types-de-plans" tabindex="-1">Deux types de plans <a class="header-anchor" href="#deux-types-de-plans" aria-label="Permalink to &quot;Deux types de plans&quot;">​</a></h2><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Plan</th><th>Usage et sortie</th></tr></thead><tbody><tr><td>Flux de valeurs</td><td>Entrées/sorties typées, logique, calcul, sélection, mémoires, fronts, temporisateurs et compteurs. 33 types implémentés ; les autres références sont marquées comme modèles. Export YAML d’automatisation HA, YAML de script HA ou fonction JavaScript avec interface hôte.</td></tr><tr><td>Flux HA natif</td><td>Importer automatisations, scripts et blueprints en blocs imbriqués. 53 types HA supplémentaires : déclencheurs, conditions, branches, boucles, attentes, variables et entrées de blueprint. Export uniquement en YAML HA natif.</td></tr></tbody></table></div><p>La simulation des flux de valeurs utilise des valeurs de démonstration/instantanées. Les blocs persistants nécessitent les helpers texte HA documentés ou un hôte mémoire JavaScript. Les flux HA natifs ne sont ni exécutés dans l’éditeur ni traduits automatiquement en JavaScript. La sortie JavaScript n’est pas un script ioBroker.</p><h2 id="connexions-a-la-souris-et-mini-vue" tabindex="-1">Connexions à la souris et mini-vue <a class="header-anchor" href="#connexions-a-la-souris-et-mini-vue" aria-label="Permalink to &quot;Connexions à la souris et mini-vue&quot;">​</a></h2><p>Maintenir le bouton de la souris sur une borne colorée, faire glisser vers une borne opposée compatible puis relâcher. Le curseur devient une croix et un aperçu du lien suit la souris. Les cibles compatibles sont marquées en vert ; les entrées incompatibles ou occupées en rouge. Le glissement d’une entrée vers une sortie fonctionne aussi. <strong>Échap</strong> ou relâcher sur une zone vide annule ; <strong>Annuler</strong> retire un lien nouvellement créé.</p><p><strong>BOOL se connecte uniquement à BOOL.</strong> Les types identiques sont compatibles ; la conversion élargissante <code>INT → REAL</code> est aussi autorisée. Les bornes explicitement <code>ANY</code> sont universelles. Nombres et textes ne sont pas convertis implicitement en BOOL. Une entrée accepte un seul lien ; types incompatibles, bornes de même direction, liens vers le même bloc et cycles sont refusés avec une explication. Au clavier, sélectionner la sortie avec Tab/Entrée, puis l’entrée et Entrée.</p><p><img src="'+n+'" alt="Bornes BOOL compatibles reliées à la souris sur .193"></p><p><img src="'+l+'" alt="Connexion STRING vers BOOL refusée avec une erreur de type explicite"></p><p>En bas à droite, la <strong>MiniMap</strong> affiche les positions colorées des blocs et la zone visible. Faire glisser dans la MiniMap pour naviguer et utiliser la molette pour zoomer. Faire glisser le canevas vide déplace la vue ; <strong>+/−</strong> règlent le zoom et <strong>Alles anzeigen</strong> cadre tous les blocs. Déplacer un bloc par son en-tête. L’attribution <strong>React Flow</strong> reste visible en bas à droite. Depuis 0.1.8, la bibliothèque fonctionne réellement dans l’éditeur ; la logique métier, la validation des types et les exportateurs restent propres à Logic Studio.</p><p><img src="'+u+'" alt="Canevas React Flow avec plan original conservé et MiniMap sur .193"></p><p><img src="'+c+'" alt="Test local React Flow avec blocs typés"></p><p>Les images suivantes documentent aussi les tests précédents de 0.1.7.</p><p><img src="'+d+'" alt="Mini-vue avec positions des blocs et cadre visible sur .193"></p><h2 id="importation-et-modification" tabindex="-1">Importation et modification <a class="header-anchor" href="#importation-et-modification" aria-label="Permalink to &quot;Importation et modification&quot;">​</a></h2><p>Ouvrir <strong>HA importieren</strong>, choisir automatisations/scripts/blueprints, puis <strong>Aus HA einlesen</strong>, un fichier YAML/JSON ou du texte. Sélectionner une entrée, vérifier l’aperçu et choisir <strong>Import übernehmen</strong>. Sauvegarder d’abord le projet existant en JSON ; des sauvegardes du projet et des sources sont aussi créées.</p><p>Le dossier de configuration HA est monté <strong>en lecture seule</strong>. L’application lit <code>automations.yaml</code>, <code>scripts.yaml</code> et les fichiers blueprint. Avant analyse, les sources sont copiées sous <code>/data/ha-source-backups/&lt;horodatage&gt;/</code> avec leurs noms d’origine. <code>secrets.yaml</code> n’est pas ouvert ; <code>!secret</code> et <code>!include</code> ne sont pas résolus. Importer manuellement les fichiers référencés par les inclusions.</p><p>Les liens orange <strong>FLOW</strong> représentent l’ordre et les branches : sortie de branche → <strong>DO</strong>, puis <strong>NEXT → DO</strong>. Les liens jaunes <strong>VALUE/REF</strong> montrent les paramètres de blueprint et leur utilisation <code>!input</code>. Configuration HA et chemins de branche sont modifiables en JSON. Les clés de paramètres/champs doivent être uniques. Les sections inconnues restent <strong>YAML_ORIGINAL</strong> ; des liens manquants peuvent bloquer l’export.</p><p><img src="'+p+'" alt="Aperçu d’importation des blueprints HA existants"></p><p>Le <strong>menu ⋮</strong> de chaque bloc propose <strong>Eigenschaften</strong> (propriétés), <strong>Duplizieren</strong> (dupliquer) et <strong>Löschen</strong> (supprimer). La duplication copie les propriétés sans liens. La suppression retire les liens associés ; Annuler les restaure. Recherche, favoris et blocs récents facilitent la sélection.</p><p><img src="'+m+'" alt="Menu à trois points d’un bloc"></p><h2 id="validation-et-limites" tabindex="-1">Validation et limites <a class="header-anchor" href="#validation-et-limites" aria-label="Permalink to &quot;Validation et limites&quot;">​</a></h2><p><strong>0.1.12 sur .193 / HA Core 2026.10.4 :</strong> Application locale mise à jour depuis 0.1.8 après sauvegarde complète. DE/EN/FR, documentation et sélection d’entités HA réelles validés. Le français reste mémorisé après rechargement du navigateur, redémarrage de l’application et nouveau chargement du projet enregistré ; l’allemand a ensuite été rétabli. Le JSON ne diffère <strong>que par la version</strong> : cinq blocs, trois liens, noms, valeurs et positions sont identiques. Le YAML généré est identique en EN et FR. Aucun appareil commandé. <strong>31 tests Node et neuf tests Python</strong> réussis. Les anciens rapports ci-dessous sont conservés comme historique.</p><p><img src="'+g+'" alt="Retour à l’allemand après redémarrage réussi sur .193"></p><p><strong>0.1.8 sur .193 / HA Core 2026.10.4 :</strong> Application locale existante mise à jour après sauvegarde complète. Connexions BOOL à la souris, refus STRING→BOOL, entrées occupées, déplacement/annulation, duplication, zoom et MiniMap validés. Le sélecteur lit les entités HA ; un script imbriqué avec If/Then/Else, Delay et Stop a été importé puis exporté sans modification de structure. Le plan original a été restauré et comparé après rechargement : <strong>identifiants, positions, paramètres et trois liens inchangés</strong>, ainsi que favoris, blocs récents et catégories repliées. Aucun appareil commandé. Construction Docker et test HTTP du conteneur réussis, ainsi que <strong>29 tests Node et huit tests Python</strong>. Images de l’interface allemande. Le changement clair/sombre n’a pas été retesté manuellement à cette étape.</p><p>La base fonctionnelle <strong>0.1.5</strong> a été testée sur <strong>.193 / HA Core 2026.10.4</strong> : import d’un blueprint réel, exemples d’automatisation/script/blueprint, exports YAML identiques sur le fond et actions du menu. <strong>0.1.6</strong> est sa première distribution publique. 22 tests Node et huit tests Python vérifient export, persistance, branches et import sûr ; les contrôles GitHub construisent aussi le conteneur.</p><p><strong>0.1.7 sur .193 / HA Core 2026.10.4 :</strong> tests réels à la souris réussis pour BOOL → BOOL et le sens inverse. STRING → BOOL et une entrée occupée ont été refusés. Mini-vue, navigation par clic et touche Début vérifiées. Le plan original a été rétabli et comparé à sa sauvegarde : <strong>cinq blocs, trois liens et tous les réglages de palette conservés</strong>, y compris après la mise à jour locale vers 0.1.7. Sauvegardes HA complète et projet/réglages séparées créées au préalable ; aucun appareil commandé. <strong>26 tests Node et huit tests Python</strong> réussissent actuellement. Les captures montrent l’interface allemande.</p><p>L’éditeur ne valide pas toute la sémantique HA : vérifier cibles, templates et sélecteurs dans HA. Commentaires, ancres YAML et mise en forme ne sont pas reconstruits. Limites : <strong>1 Mo, 200 blocs, 500 liens</strong>, imbrication limitée et jusqu’à 250 fichiers blueprint dans les dossiers habituels. Régulateurs, calendrier et sous-plans personnalisés restent partiellement des modèles.</p><p>Pour un test local, extraire tout le ZIP, installer Python 3.10+ et les dépendances <code>requirements.txt</code>, puis lancer <strong>Start-Demo.cmd</strong> sous Windows. <code>http://127.0.0.1:4180/</code> affiche des entités de démonstration sans connexion HA. Le ZIP contient aussi <code>addon/logic_studio/</code> pour une installation locale.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/issues" target="_blank" rel="noreferrer">Signaler les problèmes sur GitHub</a> avec versions, architecture et petit exemple anonymisé. Ne pas publier identifiants, automatisations personnelles ou sauvegardes complètes. Guides et rapport de test sont inclus. Licence MIT ; attribution des métadonnées de blocs dans <code>THIRD-PARTY.txt</code>.</p>',115)])])}const B=h(L,[["render",A]]);export{E as __pageData,B as default};
